package com.miniforce.service;
import com.miniforce.dto.AdminDtos.AdminDashboardResponse; import com.miniforce.repository.*; import org.springframework.stereotype.Service;
@Service public class AdminService { private final UserRepository users;private final ProblemRepository problems;private final SubmissionRepository submissions;private final DiscussionRepository discussions;private final ContestRepository contests; public AdminService(UserRepository u,ProblemRepository p,SubmissionRepository s,DiscussionRepository d,ContestRepository c){users=u;problems=p;submissions=s;discussions=d;contests=c;} public AdminDashboardResponse dashboard(){return new AdminDashboardResponse(users.count(),problems.count(),submissions.count(),discussions.countByDeletedFalse(),contests.count());} }
